// Demo: HOTP/TOTP in Hardware — TOTP code generation (RFC 6238)
function hotp(key,counter){var h=0;var s=key+counter;for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h%1000000;}
var code=hotp('SECRET-10',Math.floor(Date.now()/30000));
console.log('technique: HOTP/TOTP in Hardware');console.log('current TOTP: '+String(code).padStart(6,'0'));
console.log('valid for this 30-second window only');

